<?php
defined( 'ABSPATH' ) || exit;
function morgenbrot_rate_limited($form){$ip=sanitize_text_field($_SERVER['REMOTE_ADDR']??'local');$key='morgenbrot_rate_'.md5($form.'|'.$ip);if(get_transient($key))return true;set_transient($key,1,30);return false;}
function morgenbrot_form_redirect($result){$action=sanitize_key($_POST['morgenbrot_action']??'');$demo_key='contact'===$action?'page_contact':'page_preorder';$pages=get_posts(array('post_type'=>'page','post_status'=>'publish','numberposts'=>1,'meta_key'=>'_morgenbrot_demo_key','meta_value'=>$demo_key));$url=$pages?get_permalink($pages[0]):('contact'===$action?home_url('/kontakt/'):home_url('/vorbestellen/'));wp_safe_redirect(add_query_arg('form',$result,$url));exit;}
function morgenbrot_handle_public_forms(){
	if(empty($_POST['morgenbrot_action']))return;$action=sanitize_key($_POST['morgenbrot_action']);if(!in_array($action,array('preorder','contact'),true))return;
	if(empty($_POST['morgenbrot_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['morgenbrot_nonce'])),'morgenbrot_'.$action)||!empty($_POST['website'])||morgenbrot_rate_limited($action))morgenbrot_form_redirect('error');
	if('contact'===$action){$name=sanitize_text_field(wp_unslash($_POST['name']??''));$email=sanitize_email(wp_unslash($_POST['email']??''));$subject=sanitize_text_field(wp_unslash($_POST['subject']??''));$message=sanitize_textarea_field(wp_unslash($_POST['message']??''));if(!$name||!is_email($email)||!$subject||!$message||empty($_POST['privacy']))morgenbrot_form_redirect('invalid');$id=wp_insert_post(array('post_type'=>'bakery_contact','post_status'=>'private','post_title'=>sprintf('Kontakt: %s – %s',$name,$subject)));if(!$id||is_wp_error($id))morgenbrot_form_redirect('error');update_post_meta($id,'_morgenbrot_contact',compact('name','email','subject','message'));morgenbrot_form_redirect('contact_success');}
	$name=sanitize_text_field(wp_unslash($_POST['name']??''));$email=sanitize_email(wp_unslash($_POST['email']??''));$phone=sanitize_text_field(wp_unslash($_POST['phone']??''));$location_id=absint($_POST['location']??0);$pickup=sanitize_text_field(wp_unslash($_POST['pickup']??''));$comment=sanitize_textarea_field(wp_unslash($_POST['comment']??''));$cart=array_map('absint',(array)($_POST['cart']??array()));$items=array();$total=0.0;
	foreach($cart as$product_id=>$quantity){$product_id=absint($product_id);if($quantity<1||$quantity>50||'bakery_product'!==get_post_type($product_id)||'publish'!==get_post_status($product_id)||'out_of_stock'===morgenbrot_meta($product_id,'availability_status'))continue;$price=morgenbrot_product_price($product_id);$items[]=array('product_id'=>$product_id,'sku'=>morgenbrot_meta($product_id,'sku'),'title'=>get_the_title($product_id),'quantity'=>$quantity,'unit_price'=>$price['current']);$total+=$price['current']*$quantity;}
	try{$pickup_date=new DateTimeImmutable($pickup,wp_timezone());$pickup_ts=$pickup_date->getTimestamp();}catch(Exception$e){$pickup_ts=0;}$now=current_datetime()->getTimestamp();$max_ts=current_datetime()->modify('+90 days')->getTimestamp();if(!$name||!is_email($email)||'bakery_location'!==get_post_type($location_id)||!$items||!$pickup_ts||$pickup_ts<$now||$pickup_ts>$max_ts||empty($_POST['privacy']))morgenbrot_form_redirect('invalid');
	$items_text=implode("\n",array_map(fn($item)=>sprintf('%d × %s (%s) – %s',$item['quantity'],$item['title'],$item['sku'],morgenbrot_format_price($item['unit_price'])),$items));$location_name=get_the_title($location_id);$data=compact('name','email','phone','location_id','location_name','pickup','comment','items','items_text','total');$id=wp_insert_post(array('post_type'=>'bakery_preorder','post_status'=>'private','post_title'=>sprintf('Vorbestellung – %s – %s',$name,current_time('d.m.Y H:i'))));if(!$id||is_wp_error($id))morgenbrot_form_redirect('error');update_post_meta($id,'_morgenbrot_order',$data);update_post_meta($id,'_morgenbrot_status','new');morgenbrot_form_redirect('preorder_success');
}
add_action('template_redirect','morgenbrot_handle_public_forms');
function morgenbrot_notice(){ $result=sanitize_key($_GET['form']??'');if('preorder_success'===$result)return'<div class="notice success" role="status">Vielen Dank für Ihre Anfrage. Die Vorbestellung wird erst nach einer Bestätigung durch die Bäckerei verbindlich.</div>';if('contact_success'===$result)return'<div class="notice success" role="status">Vielen Dank. Ihre Nachricht wurde sicher und ausschließlich lokal gespeichert.</div>';if('invalid'===$result)return'<div class="notice error" role="alert">Bitte prüfen Sie alle Pflichtfelder und Ihre Auswahl.</div>';if('error'===$result)return'<div class="notice error" role="alert">Die Anfrage konnte nicht verarbeitet werden. Bitte versuchen Sie es erneut.</div>';return''; }
function morgenbrot_cart_from_request(){ $cart=array();$raw=(array)($_GET['cart']??array());foreach($raw as$id=>$qty){$id=absint($id);$qty=absint($qty);if($id&&$qty&&'bakery_product'===get_post_type($id))$cart[$id]=min(50,$qty);}if(!empty($_GET['product'])){$id=absint($_GET['product']);if('bakery_product'===get_post_type($id))$cart[$id]=min(50,max(1,absint($_GET['qty']??1)));}return$cart; }
function morgenbrot_preorder_shortcode(){
	$cart=morgenbrot_cart_from_request();$locations=get_posts(array('post_type'=>'bakery_location','post_status'=>'publish','numberposts'=>-1,'orderby'=>'title','order'=>'ASC'));ob_start();echo morgenbrot_notice();
	?><div class="preorder-app" data-preorder-app><form class="cart-form" method="get" action="<?php echo esc_url(home_url('/vorbestellung/'));?>"><h2>Ihre Auswahl</h2><div class="cart-items" aria-live="polite"><?php if(!$cart):?><div class="empty"><h3>Noch keine Produkte ausgewählt</h3><p>Stellen Sie Ihre Anfrage im Sortiment zusammen.</p><a class="button" href="<?php echo esc_url(get_post_type_archive_link('bakery_product'));?>">Zum Sortiment</a></div><?php else:$total=0;foreach($cart as$id=>$qty):$price=morgenbrot_product_price($id);$total+=$price['current']*$qty;?><article class="cart-item" data-cart-item><div><?php echo get_the_post_thumbnail($id,'thumbnail',array('alt'=>''));?><div><strong><?php echo esc_html(get_the_title($id));?></strong><small>SKU <?php echo esc_html(morgenbrot_meta($id,'sku'));?> · <?php echo esc_html(morgenbrot_format_price($price['current']));?></small></div></div><label>Menge<input type="number" min="0" max="50" name="cart[<?php echo esc_attr($id);?>]" value="<?php echo esc_attr($qty);?>"></label><button type="button" class="remove-item" aria-label="<?php echo esc_attr(get_the_title($id));?> entfernen">Entfernen</button></article><?php endforeach;?><div class="cart-total"><span>Unverbindliche Summe</span><strong><?php echo esc_html(morgenbrot_format_price($total));?></strong></div><button class="button secondary" type="submit">Auswahl aktualisieren</button><?php endif;?></div></form>
	<?php if($cart):?><form class="morgenbrot-form preorder-form" method="post" data-preorder-form><?php wp_nonce_field('morgenbrot_preorder','morgenbrot_nonce');?><input type="hidden" name="morgenbrot_action" value="preorder"><p class="hp"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></p><?php foreach($cart as$id=>$qty):?><input type="hidden" name="cart[<?php echo esc_attr($id);?>]" value="<?php echo esc_attr($qty);?>"><?php endforeach;?><h2>Abholung und Kontakt</h2><div class="form-grid"><label>Filiale <span aria-hidden="true">*</span><select name="location" required><option value="">Bitte wählen</option><?php foreach($locations as$location)printf('<option value="%d">%s</option>',$location->ID,esc_html($location->post_title));?></select></label><label>Abholdatum und Uhrzeit <span aria-hidden="true">*</span><input type="datetime-local" name="pickup" required></label><label>Name <span aria-hidden="true">*</span><input name="name" autocomplete="name" required></label><label>E-Mail <span aria-hidden="true">*</span><input type="email" name="email" autocomplete="email" required></label><label>Telefon<input type="tel" name="phone" autocomplete="tel"></label></div><label>Kommentar<textarea name="comment" rows="4"></textarea></label><label class="check"><input type="checkbox" name="privacy" value="1" required> Ich stimme der Verarbeitung meiner Angaben für diese Anfrage zu.</label><p class="form-hint">Dies ist eine unverbindliche Anfrage. Es findet keine Online-Zahlung statt.</p><div class="form-live" tabindex="-1" aria-live="polite"></div><button class="button" type="submit">Vorbestellung anfragen</button></form><?php endif;?></div><?php return ob_get_clean();
}
add_shortcode('morgenbrot_preorder','morgenbrot_preorder_shortcode');
function morgenbrot_contact_shortcode(){ob_start();echo morgenbrot_notice();?><form class="morgenbrot-form" method="post"><?php wp_nonce_field('morgenbrot_contact','morgenbrot_nonce');?><input type="hidden" name="morgenbrot_action" value="contact"><p class="hp"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></p><div class="form-grid"><label>Name <span aria-hidden="true">*</span><input name="name" autocomplete="name" required></label><label>E-Mail <span aria-hidden="true">*</span><input type="email" name="email" autocomplete="email" required></label></div><label>Betreff <span aria-hidden="true">*</span><input name="subject" required></label><label>Nachricht <span aria-hidden="true">*</span><textarea name="message" rows="6" required></textarea></label><label class="check"><input type="checkbox" name="privacy" value="1" required> Ich stimme der lokalen Speicherung meiner Angaben zu.</label><p class="form-hint">Demo-Modus: Die Nachricht wird nicht per E-Mail versendet.</p><button class="button" type="submit">Nachricht senden</button></form><?php return ob_get_clean();}
add_shortcode('morgenbrot_contact','morgenbrot_contact_shortcode');
